-- Put back the column rights migration 20261216100000 took away with the table rights.
--
-- Revoking a right on a table also revokes that right on each of its columns (PostgreSQL's REVOKE
-- does both). 20261216100000 took the table-level SELECT on products, product_variants and brands,
-- and every right on gift_card_purchases and shared_carts, which visitors and staff held only as
-- column grants: every read of the catalog and of a store's brand row failed with "permission
-- denied" from the moment it was applied (2026-11-21).
--
-- These are exactly the column grants the live database held just before it (read on 2026-11-21),
-- which are Tokyo's before the move. Cost columns stay out, as before.
GRANT SELECT (created_at, custom_domain, google_site_verification, id, is_active, logo_url, meta_description, meta_description_en, meta_title, meta_title_en, name_ar, name_en, slug) ON TABLE public.brands TO anon;
GRANT SELECT (addons, addons_total, amount, brand_id, buyer_email, buyer_name, buyer_phone, buyer_user_id, cancel_reason, cancelled_at, cancelled_by, code_sent_at, code_sent_by, created_at, currency, delivery_channel, design, gateway_reference, gift_card_id, id, lang, message, paid_at, payment_method, print_address, print_by_store, print_delivered_at, print_delivered_by, print_fee, print_phone, print_tax_rate, printed_at, printed_by, receipt_key, recipient_name, settled_by, status, total_due) ON TABLE public.gift_card_purchases TO authenticated;
GRANT SELECT (archived_at, brand_id, color, created_at, duration_minutes, fabric, id, image_url, option_five, option_four, original_price, product_id, selling_price, size, size_unit, sku, stock, stock_incubator, stock_main, updated_at) ON TABLE public.product_variants TO anon;
GRANT SELECT (archived_at, barcode, brand_id, color, created_at, duration_minutes, fabric, id, image_url, option_five, option_four, original_price, product_id, selling_price, size, size_unit, sku, stock, stock_incubator, stock_main, updated_at, user_id) ON TABLE public.product_variants TO authenticated;
GRANT SELECT (archived_at, auto_deactivated_out_of_stock, base_price, booking_buffer_minutes, booking_capacity, booking_notice_hours, booking_scope, brand_id, category, category_unavailable_until, created_at, custom_fields, description, description_ar, description_en, details, extra_hour_price, fabric_type, featured_trending, id, image_url, is_active, is_made_to_order, is_package, item_kind, made_to_order_available, made_to_order_paused_at, media, name, name_ar, name_en, occasion, seo_description_ar, seo_description_en, seo_title_ar, seo_title_en, service_includes, service_location, show_sale_badge, size_guide_hidden, size_guide_id, tracks_inventory, unavailable_until, updated_at, variant_label_color, variant_label_color_ar, variant_label_color_en, variant_label_fabric, variant_label_fabric_ar, variant_label_fabric_en, variant_label_five_ar, variant_label_five_en, variant_label_four_ar, variant_label_four_en, variant_label_size, variant_label_size_ar, variant_label_size_en) ON TABLE public.products TO anon;
GRANT SELECT (archived_at, auto_deactivated_out_of_stock, base_price, booking_buffer_minutes, booking_capacity, booking_notice_hours, booking_scope, brand_id, category, category_unavailable_until, created_at, custom_fields, description, description_ar, description_en, details, extra_hour_price, fabric_type, featured_trending, id, image_url, is_active, is_made_to_order, is_package, item_kind, made_to_order_available, made_to_order_limit_set_at, made_to_order_paused_at, media, name, name_ar, name_en, occasion, seo_description_ar, seo_description_en, seo_title_ar, seo_title_en, service_includes, service_location, show_sale_badge, size_guide_hidden, size_guide_id, tracks_inventory, unavailable_until, updated_at, user_id, variant_label_color, variant_label_color_ar, variant_label_color_en, variant_label_fabric, variant_label_fabric_ar, variant_label_fabric_en, variant_label_five_ar, variant_label_five_en, variant_label_four_ar, variant_label_four_en, variant_label_size, variant_label_size_ar, variant_label_size_en) ON TABLE public.products TO authenticated;
GRANT INSERT (brand_id, brand_slug, code, items) ON TABLE public.shared_carts TO anon;
GRANT INSERT (brand_id, brand_slug, code, items) ON TABLE public.shared_carts TO authenticated;
